<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
</head>
<body>
<div id="sb-remote-loading" style="padding:12px 16px;font-size:13px;color:#888;text-align:center;">状态栏加载中...</div>
<script type="module">
(async () => {
  const URL = 'https://gcore.jsdelivr.net/gh/yizichen123/zhuangtailan@v1.0/statusbar/index.html';
  try {
    const res = await fetch(URL);
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const html = await res.text();
    const doc = new DOMParser().parseFromString(html, 'text/html');
    const loading = document.getElementById('sb-remote-loading');
    if (loading) loading.remove();
    for (const node of Array.from(doc.head.children)) {
      if (node.tagName === 'META' || node.tagName === 'TITLE') continue;
      document.head.appendChild(document.importNode(node, true));
    }
    for (const node of Array.from(doc.body.childNodes)) {
      if (node.nodeType === 1 && node.tagName === 'SCRIPT') {
        const s = document.createElement('script');
        for (const attr of node.attributes) s.setAttribute(attr.name, attr.value);
        s.textContent = node.textContent;
        document.body.appendChild(s);
      } else {
        document.body.appendChild(document.importNode(node, true));
      }
    }
  } catch (err) {
    const el = document.getElementById('sb-remote-loading');
    if (el) el.textContent = '状态栏加载失败（请检查网络）：' + (err && err.message ? err.message : err);
  }
})();
</script>
</body>
</html>
